/bin/bash -lc "python3 - <<'PY'
import json, urllib.request
from datetime import date, datetime
facility=233869
for month in ['2026-05-01','2026-06-01','2026-07-01','2026-08-01','2026-09-01','2026-10-01']:
    url=f'https://www.recreation.gov/api/camps/availability/campground/{facility}/month?start_date={month}T00%3A00%3A00.000Z'
    with urllib.request.urlopen(url) as r:
        data=json.load(r)
    found=[]
    for sid, site in data.get('campsites',{}).items():
        name=site.get('site') or site.get('campsite_id') or sid
        for d, status in site.get('availabilities',{}).items():
            if status == 'Available':
                found.append((d[:10], name, sid))
    if found:
        found.sort()
        print('MONTH', month, 'first', found[0])
        for row in found[:20]: print(row)
        break
PY"

